class Node:
    __slots__ = ['value', 'prev', 'next']
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    head = None
    tail = None
    for line in input[1:n+1]:
        cmd = line.split()
        if cmd[0] == 'insert':
            x = int(cmd[1])
            new_node = Node(x)
            if head is None:
                head = new_node
                tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif cmd[0] == 'delete':
            x = int(cmd[1])
            current = head
            while current is not None:
                if current.value == x:
                    prev_node = current.prev
                    next_node = current.next
                    if prev_node is None:
                        head = next_node
                    else:
                        prev_node.next = next_node
                    if next_node is None:
                        tail = prev_node
                    else:
                        next_node.prev = prev_node
                    break
                current = current.next
        elif cmd[0] == 'deleteFirst':
            if head is not None:
                next_node = head.next
                if next_node is None:
                    head = None
                    tail = None
                else:
                    head = next_node
                    head.prev = None
        elif cmd[0] == 'deleteLast':
            if tail is not None:
                prev_node = tail.prev
                if prev_node is None:
                    head = None
                    tail = None
                else:
                    tail = prev_node
                    tail.next = None
    # Collect the elements
